export const getLineIntersectPlane = (x1: number, y1: number, x2: number, y2: number, x3: number, y3: number, x4: number, y4: number) => {
    // Check if none of the lines are of length 0
    if ((x1 === x2 && y1 === y2) || (x3 === x4 && y3 === y4)) {
      return undefined;
    }
  
    const denominator = ((y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1));
  
    // Lines are parallel
    if (denominator === 0) {
      return undefined;
    }
  
    const ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denominator;
    const ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / denominator;
  
    // is the intersection along the segments
    if (ua < 0 || ua > 1 || ub < 0 || ub > 1) {
      return undefined;
    }
  
    // Return a object with the x and y coordinates of the intersection
    const x = x1 + ua * (x2 - x1);
    const y = y1 + ua * (y2 - y1);
  
    return [x, y];
};

/**
 * 
 * @param lns =[{
 *      p0: { 
 *          x: number,
 *          y: number,
 *          z: number,
 *      },
 *      p1: { 
 *          x: number,
 *          y: number,
 *          z: number,
 *      }
 *  }, ... 
 * ]
 * @returns 
 */
export const getLineSeg = (lns: any) => {
    const lineSeg = [];

    for (let i = 0; i < lns.length; ++i) {
        const ln0 = lns[i];
        const inters = [];

        for (let j = 0; j < lns.length; ++j) {
            const ln1 = lns[j];
            if (ln0 === ln1) continue;

            const interVec = getLineIntersectPlane(ln0.p0.x, ln0.p0.y, ln0.p1.x, ln0.p1.y, ln1.p0.x, ln1.p0.y, ln1.p1.x, ln1.p1.y);
            if (interVec) {
                inters.push({
                        x: interVec[0],
                        y: interVec[1],
                        z:0
                    });
            } 
        }

        if (inters.length === 0) {
            lineSeg.push(ln0)
        } else if (inters.length === 1) {
            lineSeg.push({
                p0: ln0.p0,
                p1: inters[0]
            });
            lineSeg.push({
                p0: inters[0],
                p1: ln0.p1
            });
        } else {  
            const dis =[];
            for(let j = 0 ; j < inters.length; ++j) {
                dis.push(distanceTo(ln0.p0.x, ln0.p0.y, ln0.p0.z, inters[j].x, inters[j].y, inters[j].z));
            }
            const newIndex = getIndexSorting(dis);
            lineSeg.push({
                p0: ln0.p0,
                p1: inters[newIndex[0]]
            })
            for(let j = 0 ; j < newIndex.length -1 ; ++j) {
                lineSeg.push({
                    p0: inters[newIndex[j]],
                    p1: inters[newIndex[j+1]]
                });
            }
            lineSeg.push({
                p0: inters[newIndex[newIndex.length-1]],
                p1: ln0.p1,
            })

        }

    }
    return lineSeg;
};
const getIndexSorting = (d: any) => {
    return d.map((val: any, ind: any) => {return {ind, val}}).sort((a: any, b: any) => {return a.val > b.val ? 1 : a.val === b.val ? 0 : -1 }).map((obj: any) => obj.ind);
}
export const distanceTo = (x0: number, y0: number, z0: number, x1: number, y1: number, z1: number): number  => {
    return Math.sqrt((x0 - x1) * (x0 - x1) + (y0 - y1) * (y0 - y1) + (z0 - z1) * (z0 - z1));
}